cr="upgrade-test-slo"
namespace="default"
name="${NAME:?NAME is required}"
id_file="${RUNNER_TEMP:-/tmp}/upgrade-test-slo.id"

jsonpath() {
    kubectl get slo "$cr" -n "$namespace" -o jsonpath="$1"
